package org.example;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

@DisplayName("Testes para AddExpression")
class AddExpressionTest {

    @Test
    @DisplayName("Deve somar dois números positivos")
    void testAddTwoPositiveNumbers() {
        Expression expression = new AddExpression(
            new NumberExpression(5),
            new NumberExpression(3)
        );
        assertEquals(8.0, expression.interpret());
    }

    @Test
    @DisplayName("Deve somar número positivo com negativo")
    void testAddPositiveWithNegative() {
        Expression expression = new AddExpression(
            new NumberExpression(10),
            new NumberExpression(-3)
        );
        assertEquals(7.0, expression.interpret());
    }

    @Test
    @DisplayName("Deve somar dois números negativos")
    void testAddTwoNegativeNumbers() {
        Expression expression = new AddExpression(
            new NumberExpression(-5),
            new NumberExpression(-3)
        );
        assertEquals(-8.0, expression.interpret());
    }

    @Test
    @DisplayName("Deve somar com zero")
    void testAddWithZero() {
        Expression expression = new AddExpression(
            new NumberExpression(10),
            new NumberExpression(0)
        );
        assertEquals(10.0, expression.interpret());
    }

    @Test
    @DisplayName("Deve somar números decimais")
    void testAddDecimalNumbers() {
        Expression expression = new AddExpression(
            new NumberExpression(2.5),
            new NumberExpression(3.5)
        );
        assertEquals(6.0, expression.interpret());
    }

    @Test
    @DisplayName("Deve somar expressões aninhadas")
    void testAddNestedExpressions() {
        // (5 + 3) + (2 + 1)
        Expression expression = new AddExpression(
            new AddExpression(new NumberExpression(5), new NumberExpression(3)),
            new AddExpression(new NumberExpression(2), new NumberExpression(1))
        );
        assertEquals(11.0, expression.interpret());
    }

    @Test
    @DisplayName("Deve retornar string formatada")
    void testToString() {
        Expression expression = new AddExpression(
            new NumberExpression(5),
            new NumberExpression(3)
        );
        assertTrue(expression.toString().contains("+"));
    }
}

package org.example;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

@DisplayName("Testes para DivideExpression")
class DivideExpressionTest {

    @Test
    @DisplayName("Deve dividir dois números positivos")
    void testDivideTwoPositiveNumbers() {
        Expression expression = new DivideExpression(
            new NumberExpression(20),
            new NumberExpression(4)
        );
        assertEquals(5.0, expression.interpret());
    }

    @Test
    @DisplayName("Deve dividir resultando em número decimal")
    void testDivideResultDecimal() {
        Expression expression = new DivideExpression(
            new NumberExpression(10),
            new NumberExpression(3)
        );
        assertEquals(10.0 / 3, expression.interpret(), 0.0001);
    }

    @Test
    @DisplayName("Deve dividir número positivo com negativo")
    void testDividePositiveWithNegative() {
        Expression expression = new DivideExpression(
            new NumberExpression(10),
            new NumberExpression(-2)
        );
        assertEquals(-5.0, expression.interpret());
    }

    @Test
    @DisplayName("Deve dividir dois números negativos")
    void testDivideTwoNegativeNumbers() {
        Expression expression = new DivideExpression(
            new NumberExpression(-20),
            new NumberExpression(-4)
        );
        assertEquals(5.0, expression.interpret());
    }

    @Test
    @DisplayName("Deve dividir zero por número")
    void testDivideZeroByNumber() {
        Expression expression = new DivideExpression(
            new NumberExpression(0),
            new NumberExpression(5)
        );
        assertEquals(0.0, expression.interpret());
    }

    @Test
    @DisplayName("Deve lançar exceção ao dividir por zero")
    void testDivideByZeroThrowsException() {
        Expression expression = new DivideExpression(
            new NumberExpression(15),
            new NumberExpression(0)
        );
        assertThrows(ArithmeticException.class, expression::interpret);
    }

    @Test
    @DisplayName("Deve retornar mensagem de erro correto ao dividir por zero")
    void testDivideByZeroErrorMessage() {
        Expression expression = new DivideExpression(
            new NumberExpression(20),
            new NumberExpression(0)
        );
        ArithmeticException exception = assertThrows(
            ArithmeticException.class,
            expression::interpret
        );
        assertEquals("Divisão por zero!", exception.getMessage());
    }

    @Test
    @DisplayName("Deve dividir números decimais")
    void testDivideDecimalNumbers() {
        Expression expression = new DivideExpression(
            new NumberExpression(10.5),
            new NumberExpression(2.0)
        );
        assertEquals(5.25, expression.interpret(), 0.01);
    }

    @Test
    @DisplayName("Deve dividir expressões aninhadas")
    void testDivideNestedExpressions() {
        // ((10 + 5) - 3) / 2 = 12 / 2 = 6
        Expression expression = new DivideExpression(
            new SubtractExpression(
                new AddExpression(new NumberExpression(10), new NumberExpression(5)),
                new NumberExpression(3)
            ),
            new NumberExpression(2)
        );
        assertEquals(6.0, expression.interpret());
    }

    @Test
    @DisplayName("Deve retornar string formatada")
    void testToString() {
        Expression expression = new DivideExpression(
            new NumberExpression(20),
            new NumberExpression(4)
        );
        assertTrue(expression.toString().contains("/"));
    }
}

package org.example;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

@DisplayName("Testes de Integração - Expressões Complexas")
class ExpressionIntegrationTest {

    @Test
    @DisplayName("Deve calcular: (5 + 3) * 2 = 16")
    void testComplexExpression1() {
        Expression expression = new MultiplyExpression(
            new AddExpression(new NumberExpression(5), new NumberExpression(3)),
            new NumberExpression(2)
        );
        assertEquals(16.0, expression.interpret());
    }

    @Test
    @DisplayName("Deve calcular: ((10 + 5) - 3) / 2 = 6")
    void testComplexExpression2() {
        Expression expression = new DivideExpression(
            new SubtractExpression(
                new AddExpression(new NumberExpression(10), new NumberExpression(5)),
                new NumberExpression(3)
            ),
            new NumberExpression(2)
        );
        assertEquals(6.0, expression.interpret());
    }

    @Test
    @DisplayName("Deve calcular: (20 / 4) + (3 * 2) = 11")
    void testComplexExpression3() {
        Expression expression = new AddExpression(
            new DivideExpression(new NumberExpression(20), new NumberExpression(4)),
            new MultiplyExpression(new NumberExpression(3), new NumberExpression(2))
        );
        assertEquals(11.0, expression.interpret());
    }

    @Test
    @DisplayName("Deve calcular: ((100 / 5) - 10) * 2 = 20")
    void testComplexExpression4() {
        Expression expression = new MultiplyExpression(
            new SubtractExpression(
                new DivideExpression(new NumberExpression(100), new NumberExpression(5)),
                new NumberExpression(10)
            ),
            new NumberExpression(2)
        );
        assertEquals(20.0, expression.interpret());
    }

    @Test
    @DisplayName("Deve calcular: (8 * 3) - (10 + 4) = 14")
    void testComplexExpression5() {
        Expression expression = new SubtractExpression(
            new MultiplyExpression(new NumberExpression(8), new NumberExpression(3)),
            new AddExpression(new NumberExpression(10), new NumberExpression(4))
        );
        assertEquals(14.0, expression.interpret());
    }

    @Test
    @DisplayName("Deve calcular: (50 - 20) / (10 - 5) = 6")
    void testComplexExpression6() {
        Expression expression = new DivideExpression(
            new SubtractExpression(new NumberExpression(50), new NumberExpression(20)),
            new SubtractExpression(new NumberExpression(10), new NumberExpression(5))
        );
        assertEquals(6.0, expression.interpret());
    }

    @Test
    @DisplayName("Deve calcular: ((2 + 3) * (4 + 1)) / 5 = 5")
    void testComplexExpression7() {
        Expression expression = new DivideExpression(
            new MultiplyExpression(
                new AddExpression(new NumberExpression(2), new NumberExpression(3)),
                new AddExpression(new NumberExpression(4), new NumberExpression(1))
            ),
            new NumberExpression(5)
        );
        assertEquals(5.0, expression.interpret());
    }

    @Test
    @DisplayName("Deve manter precisão com números decimais em expressão complexa")
    void testDecimalPrecision() {
        // (5.5 + 2.5) * 2 = 16.0
        Expression expression = new MultiplyExpression(
            new AddExpression(new NumberExpression(5.5), new NumberExpression(2.5)),
            new NumberExpression(2)
        );
        assertEquals(16.0, expression.interpret());
    }

    @Test
    @DisplayName("Deve avaliar com números negativos")
    void testNegativeNumbers() {
        // (-10 + 5) * (-2) = 10
        Expression expression = new MultiplyExpression(
            new AddExpression(new NumberExpression(-10), new NumberExpression(5)),
            new NumberExpression(-2)
        );
        assertEquals(10.0, expression.interpret());
    }

    @Test
    @DisplayName("Deve retornar string corretamente formatada para expressão complexa")
    void testComplexToString() {
        Expression expression = new MultiplyExpression(
            new AddExpression(new NumberExpression(5), new NumberExpression(3)),
            new NumberExpression(2)
        );
        String result = expression.toString();
        assertTrue(result.contains("+"));
        assertTrue(result.contains("*"));
    }
}

package org.example;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

@DisplayName("Testes para MultiplyExpression")
class MultiplyExpressionTest {

    @Test
    @DisplayName("Deve multiplicar dois números positivos")
    void testMultiplyTwoPositiveNumbers() {
        Expression expression = new MultiplyExpression(
            new NumberExpression(7),
            new NumberExpression(6)
        );
        assertEquals(42.0, expression.interpret());
    }

    @Test
    @DisplayName("Deve multiplicar número positivo com negativo")
    void testMultiplyPositiveWithNegative() {
        Expression expression = new MultiplyExpression(
            new NumberExpression(5),
            new NumberExpression(-3)
        );
        assertEquals(-15.0, expression.interpret());
    }

    @Test
    @DisplayName("Deve multiplicar dois números negativos")
    void testMultiplyTwoNegativeNumbers() {
        Expression expression = new MultiplyExpression(
            new NumberExpression(-5),
            new NumberExpression(-3)
        );
        assertEquals(15.0, expression.interpret());
    }

    @Test
    @DisplayName("Deve multiplicar por zero")
    void testMultiplyByZero() {
        Expression expression = new MultiplyExpression(
            new NumberExpression(10),
            new NumberExpression(0)
        );
        assertEquals(0.0, expression.interpret());
    }

    @Test
    @DisplayName("Deve multiplicar números decimais")
    void testMultiplyDecimalNumbers() {
        Expression expression = new MultiplyExpression(
            new NumberExpression(2.5),
            new NumberExpression(4)
        );
        assertEquals(10.0, expression.interpret());
    }

    @Test
    @DisplayName("Deve multiplicar expressões aninhadas")
    void testMultiplyNestedExpressions() {
        // (5 + 3) * 2
        Expression expression = new MultiplyExpression(
            new AddExpression(new NumberExpression(5), new NumberExpression(3)),
            new NumberExpression(2)
        );
        assertEquals(16.0, expression.interpret());
    }

    @Test
    @DisplayName("Deve respeitar precedência com subtração")
    void testMultiplyPrecedence() {
        // 10 - 3 * 2 (sem parênteses, interpretando como (10 - 3) * 2)
        Expression expression = new MultiplyExpression(
            new SubtractExpression(new NumberExpression(10), new NumberExpression(3)),
            new NumberExpression(2)
        );
        assertEquals(14.0, expression.interpret());
    }

    @Test
    @DisplayName("Deve retornar string formatada")
    void testToString() {
        Expression expression = new MultiplyExpression(
            new NumberExpression(7),
            new NumberExpression(6)
        );
        assertTrue(expression.toString().contains("*"));
    }
}

package org.example;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

@DisplayName("Testes para NumberExpression")
class NumberExpressionTest {

    @Test
    @DisplayName("Deve interpretar um número inteiro positivo")
    void testInterpretPositiveInteger() {
        Expression expression = new NumberExpression(5);
        assertEquals(5.0, expression.interpret());
    }

    @Test
    @DisplayName("Deve interpretar um número inteiro negativo")
    void testInterpretNegativeInteger() {
        Expression expression = new NumberExpression(-10);
        assertEquals(-10.0, expression.interpret());
    }

    @Test
    @DisplayName("Deve interpretar número decimal")
    void testInterpretDecimal() {
        Expression expression = new NumberExpression(3.14);
        assertEquals(3.14, expression.interpret());
    }

    @Test
    @DisplayName("Deve interpretar zero")
    void testInterpretZero() {
        Expression expression = new NumberExpression(0);
        assertEquals(0.0, expression.interpret());
    }

    @Test
    @DisplayName("Deve retornar string com o valor do número")
    void testToString() {
        Expression expression = new NumberExpression(42);
        assertEquals("42.0", expression.toString());
    }
}

package org.example;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

@DisplayName("Testes para SubtractExpression")
class SubtractExpressionTest {

    @Test
    @DisplayName("Deve subtrair dois números positivos")
    void testSubtractTwoPositiveNumbers() {
        Expression expression = new SubtractExpression(
            new NumberExpression(10),
            new NumberExpression(3)
        );
        assertEquals(7.0, expression.interpret());
    }

    @Test
    @DisplayName("Deve subtrair resultando em número negativo")
    void testSubtractResultNegative() {
        Expression expression = new SubtractExpression(
            new NumberExpression(3),
            new NumberExpression(10)
        );
        assertEquals(-7.0, expression.interpret());
    }

    @Test
    @DisplayName("Deve subtrair número negativo (adição)")
    void testSubtractNegativeNumber() {
        Expression expression = new SubtractExpression(
            new NumberExpression(10),
            new NumberExpression(-5)
        );
        assertEquals(15.0, expression.interpret());
    }

    @Test
    @DisplayName("Deve subtrair com zero")
    void testSubtractWithZero() {
        Expression expression = new SubtractExpression(
            new NumberExpression(10),
            new NumberExpression(0)
        );
        assertEquals(10.0, expression.interpret());
    }

    @Test
    @DisplayName("Deve subtrair números decimais")
    void testSubtractDecimalNumbers() {
        Expression expression = new SubtractExpression(
            new NumberExpression(10.5),
            new NumberExpression(3.2)
        );
        assertEquals(7.3, expression.interpret(), 0.01);
    }

    @Test
    @DisplayName("Deve subtrair expressões aninhadas")
    void testSubtractNestedExpressions() {
        // (10 - 3) - (2 - 1)
        Expression expression = new SubtractExpression(
            new SubtractExpression(new NumberExpression(10), new NumberExpression(3)),
            new SubtractExpression(new NumberExpression(2), new NumberExpression(1))
        );
        assertEquals(6.0, expression.interpret());
    }

    @Test
    @DisplayName("Deve retornar string formatada")
    void testToString() {
        Expression expression = new SubtractExpression(
            new NumberExpression(10),
            new NumberExpression(3)
        );
        assertTrue(expression.toString().contains("-"));
    }
}
